#ifndef FE2_NAVIGATION_NAVIGATION_TABLES_H
#define FE2_NAVIGATION_NAVIGATION_TABLES_H

/* Native navigation tables (generated by tools/navigation_tables_c.py). */
#include <stdint.h>

enum { FE2_NAVIGATION_TEXT_BYTES = 71 };

/* Text directory: 0 the time point (parameters 1 and 2, the time), 2 the
 * autopilot target prompt. */
extern const uint8_t *fe2_navigation_text_directory;
/* The time slider: left, top, right, bottom, event 0x80, end 0xffff. */
extern const uint16_t *fe2_navigation_slider_widgets;
/* Glyph string drawn left of the autopilot target. */
extern const uint8_t *fe2_navigation_target_marker;
/* Marker size by model size / 16 (sizes up to 300). */
extern const uint8_t *fe2_navigation_marker_sizes;

#endif
